Module SGPFX.
Section WithSegs.
Variable segs : list Segment. Context {bmK : BMode}.
Variable IT : itab.
Variables x_cpy x_set x_len ro_lo ro_hi : Z.
Variable BFUEL : nat.
Variable A : APC.atable.
Variable nx0 : nat.
Variable BR : list SGP.bfact.
Variable XSTEP : list (expr * Z * expr) -> nat -> sym_state -> option sym_state.
Variable XSTEP2 : list (expr * Z * expr) -> nat -> sym_state -> option (sym_state * sym_state).
Hypothesis IT_ok : itab_sound segs IT.

(* [comment removed for export] *)
Lemma step_block_sound_fx : forall (fx : FPState) stops ss w ss' w' E R M rom,
  SR.closed ss w = true -> SR.step_block segs IT BFUEL stops ss w = Some (ss', w') -> SR.INV segs E ss w R M ->
  exists E' R', env_agree (s_next ss) E E' /\ (s_next ss <= s_next ss')%nat /\ SR.INV segs E' ss' w' R' M /\
    msteps segs (@mkst fx R (Z_to_bv 64 (s_pc ss)) (SR.wden segs E M w) rom)
                (@mkst fx R' (Z_to_bv 64 (s_pc ss')) (SR.wden segs E' M w') rom).
Proof.
  intros fx stops ss w ss' w' E R M rom Hcl H [HR HK].
  destruct (SR.closed_parts ss w Hcl) as (Fsr & Fkn & Fw & Flog).
  unfold SR.step_block in H.
  destruct ss as [p sr log k nx rsv]. cbn [s_pc s_regs s_log s_know s_next] in *. subst log.
  set (ss1 := sym_execTX segs IT 0%nat BFUEL true stops (SSR p sr [] k nx rsv)) in H.
  destruct (carry (s_log ss1) (s_know ss1) []) as [[kn' scs] hs] eqn:Hc.
  destruct scs; [|discriminate]. injection H as <- <-.
  assert (Hx : sym_execTX segs IT 0%nat BFUEL true stops (SS p sr [] k nx) = ss1).
  { subst ss1. unfold sym_execTX. reflexivity. }
  pose proof (@runTX_sound fx segs IT 0%nat BFUEL stops p sr k nx E (SR.wden segs E M w) rom R IT_ok HR HK Fsr Fkn) as X.
  cbn zeta in X. rewrite Hx in X. destruct X as (E' & R' & Hag & Hle & HR' & Hlf & HK' & Hms & _).
  exists E', R'. split; [exact Hag|]. split; [exact Hle|].
  assert (Hw : SR.wden segs E' M w = SR.wden segs E M w) by (symmetry; eapply SR.wden_agree; [exact Hag | exact Fw]).
  split.
  - split; cbn [s_regs s_know]; [exact HR'|].
    rewrite SR.wden_wlog, Hw. eapply carry_after; [exact Hc | exact Hlf | exact HK' | constructor].
  - cbn [s_pc]. rewrite SR.wden_wlog, Hw. exact Hms.
Qed.

(* [comment removed for export] *)
Lemma step1_sound_fx : forall (F : list SGP.region) (M0 : word -> option byte),
  forallb (SGP.region_vars_lt nx0) F = true -> SGP.bfacts_vars_lt BR nx0 = true ->
  forall (fx : FPState) stops ss ss' E R Mc,
  SGP.step1 segs IT x_cpy x_set x_len ro_lo ro_hi BFUEL F (SR.SBlock stops) ss = Some ss' -> SGP.INV2 segs nx0 BR F M0 E ss R Mc ->
  exists E' R' Mc', env_agree (s_next ss) E E' /\ (s_next ss <= s_next ss')%nat /\ SGP.INV2 segs nx0 BR F M0 E' ss' R' Mc'
    /\ msteps segs (@mkst fx R (Z_to_bv 64 (s_pc ss)) Mc (seg_rom segs)) (@mkst fx R' (Z_to_bv 64 (s_pc ss')) Mc' (seg_rom segs)).
Proof.
  intros F M0 Fvars BRvars fx stops ss ss' E R Mc H HI. unfold SGP.step1 in H.
  destruct (SR.seg_step segs IT x_cpy x_set x_len ro_lo ro_hi BFUEL (SR.SBlock stops) ss []) as [[ss1 w']|] eqn:Hs; [|discriminate].
  destruct (forallb (SGP.went_withinX (s_know ss1) F) w') eqn:Hw; [|discriminate]. injection H as <-.
  unfold SR.seg_step in Hs. destruct (SR.closed ss []) eqn:Hcl; [|discriminate]. cbn [negb] in Hs.
  destruct (step_block_sound_fx fx stops ss [] ss1 w' E R Mc (seg_rom segs) Hcl Hs) as (E' & R' & Hag & Hle & [HR' HK'] & Hms).
  { split; [exact (SGP.i_regs _ _ _ _ _ _ _ _ _ HI) | cbn [SR.wden]; exact (SGP.i_know _ _ _ _ _ _ _ _ _ HI)]. }
  exists E', R', (SR.wden segs E' Mc w').
  split; [exact Hag|]. split; [exact Hle|]. split.
  - pose proof (APS.env_agree_le nx0 (s_next ss) E E' Hag (SGP.i_nx _ _ _ _ _ _ _ _ _ HI)) as Hag0.
    pose proof (SGP.regions_ok_agree nx0 F Fvars E E' Hag0 (SGP.i_flat _ _ _ _ _ _ _ _ _ HI)) as Hfl'.
    constructor; [exact HR' | exact HK' | | | exact Hfl' | pose proof (SGP.i_nx _ _ _ _ _ _ _ _ _ HI); lia
                | exact (SGP.bfacts_agree nx0 BR BRvars E E' Hag0 (SGP.i_bf _ _ _ _ _ _ _ _ _ HI))].
    + intros a Ha. rewrite (SGP.wden_frame_sem segs F E' Mc w' a (SGP.went_withinX_sound segs F E' _ (s_know ss1) w' HK' Hfl' Hw) (SGP.regions_ok_flat E' F Hfl') Ha).
      apply (SGP.i_frame _ _ _ _ _ _ _ _ _ HI). eapply SGP.outside_agree; [exact Fvars | exact Hag0 | exact Ha].
    + eapply mem_grows_trans; [exact (SGP.i_grows _ _ _ _ _ _ _ _ _ HI) | apply SGP.wden_grows].
  - cbn [SR.wden] in Hms. exact Hms.
Qed.

(* [comment removed for export] *)
Theorem plan_entry_sound_fx :
  forall (F : list SGP.region) (PSS : list SR.post_spec) stops i pc0 sr0 kn0 (fx : FPState) E R M,
  SGP.cert_ok segs IT x_cpy x_set x_len ro_lo ro_hi BFUEL A nx0 BR XSTEP XSTEP2 F PSS (SGP.PStep (SR.SBlock stops) (SGP.PEnd i)) pc0 sr0 kn0 = true ->
  regs_ok E sr0 R -> know_ok segs E M kn0 -> SGP.bfacts_ok BR E ->
  exists E' R' M' ps,
       nth_error PSS i = Some ps
    /\ env_agree nx0 E E'
    /\ msteps segs (@mkst fx R (Z_to_bv 64 pc0) M (seg_rom segs)) (@mkst fx R' (Z_to_bv 64 (SR.ps_pc ps)) M' (seg_rom segs))
    /\ (forall i e, In (i, e) (SR.ps_regs ps) -> (0 < i < 32)%nat /\ getr R' (Z_to_bv 5 (Z.of_nat i)) = edenot E' e)
    /\ getr R' (Z_to_bv 5 0) = Z_to_bv 64 0
    /\ SGP.regions_ok E' F
    /\ (forall a : word, SGP.outside E' F a -> M' a = M a)
    /\ (forall K, In K (SR.ps_cells ps) -> kentry_ok segs E' M' K)
    /\ mem_grows M M'.
Proof.
  intros F PSS stops i pc0 sr0 kn0 fx E R M Hc HR HK HBF.
  unfold SGP.cert_ok in Hc. apply andb_prop in Hc as [Hc Hchk]. apply andb_prop in Hc as [Hc Hbv]. apply andb_prop in Hc as [Hflat Hvars].
  assert (HI : SGP.INV2 segs nx0 BR F M E (SS pc0 sr0 [] kn0 nx0) R M).
  { constructor; cbn [s_regs s_know s_next]; [exact HR | exact HK | intros; reflexivity | apply mem_grows_refl | | lia | exact HBF].
    unfold SGP.regions_ok. apply Forall_forall. intros r Hin. rewrite forallb_forall in Hflat.
    exact (SGP.region_flat_chkX_sound segs E M kn0 r HK (Hflat r Hin)). }
  cbn [SGP.check] in Hchk. apply andb_prop in Hchk as [_ Hchk].
  destruct (SGP.step1 segs IT x_cpy x_set x_len ro_lo ro_hi BFUEL F (SR.SBlock stops) (SS pc0 sr0 [] kn0 nx0)) as [ss1|] eqn:Hs; [|discriminate].
  apply andb_prop in Hchk as [_ Hend].
  destruct (nth_error PSS i) as [ps|] eqn:Hps; [|discriminate].
  destruct (step1_sound_fx F M Hvars Hbv fx stops _ ss1 E R M Hs HI) as (E' & R' & M' & Hag & Hle & HI' & Hms).
  destruct (SGP.end_ok_sound segs nx0 BR F M ps ss1 E' R' M' Hend HI') as (Hpc2 & Hregs & Hcells).
  exists E', R', M', ps. split; [reflexivity|]. split; [exact Hag|].
  split; [rewrite <- Hpc2; exact Hms|]. split; [exact Hregs|].
  split; [replace (Z_to_bv 5 0) with (0%bv : bv 5) by (apply bv_eq; reflexivity); apply getr_zero|].
  split; [exact (SGP.i_flat _ _ _ _ _ _ _ _ _ HI')|]. split; [exact (SGP.i_frame _ _ _ _ _ _ _ _ _ HI')|].
  split; [exact Hcells | exact (SGP.i_grows _ _ _ _ _ _ _ _ _ HI')].
Qed.
End WithSegs.
End SGPFX.

